def find_chains(N):
    chains = {}
    for k in range(1, N + 1):
        if k % 2 == 0:
            continue

        chain = []
        current = k
        while current <= N:
            chain.append(current)
            current *= 2

        chains[k] = chain
    return chains

N = 40
chains_dict = find_chains(N)
print(f"Total number of chains: {len(chains_dict)}")

# Print out the chains and their lengths for analysis
for k, chain in chains_dict.items():
    print(f"C_{k} (Length {len(chain)}): {chain}")

